import React, { useState, useEffect } from 'react';
import * as ReactRouterDOM from 'react-router-dom';
import { Procedure } from './types';
import Layout from './components/Layout';
import HomePage from './pages/HomePage';
import CatalogPage from './pages/CatalogPage';
import AboutPage from './pages/AboutPage';
import BookingModal from './components/BookingModal';

const AppContent: React.FC = () => {
  const [selectedProcedure, setSelectedProcedure] = useState<Procedure | null>(null);
  const [isBookingOpen, setIsBookingOpen] = useState(false);
  const location = ReactRouterDOM.useLocation();

  // Scroll to top on route change
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [location.pathname]);

  // Lock body scroll when modal is open
  useEffect(() => {
    if (isBookingOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
  }, [isBookingOpen]);

  const openBooking = (procedure: Procedure) => {
    setSelectedProcedure(procedure);
    setIsBookingOpen(true);
  };

  const closeBooking = () => {
    setIsBookingOpen(false);
    // Small delay to clear data after animation
    setTimeout(() => setSelectedProcedure(null), 300);
  };

  return (
    <Layout>
      <ReactRouterDOM.Routes>
        <ReactRouterDOM.Route path="/" element={<HomePage />} />
        <ReactRouterDOM.Route path="/catalogo" element={<CatalogPage onBook={openBooking} />} />
        <ReactRouterDOM.Route path="/sobre" element={<AboutPage />} />
      </ReactRouterDOM.Routes>

      <BookingModal 
        isOpen={isBookingOpen} 
        onClose={closeBooking} 
        procedure={selectedProcedure} 
      />
    </Layout>
  );
};

const App: React.FC = () => {
  return (
    <ReactRouterDOM.HashRouter>
      <AppContent />
    </ReactRouterDOM.HashRouter>
  );
};

export default App;

