export default ProcedureCard;

import React, { useState, useEffect } from 'react';
import { Procedure, BookingFormData } from '../types';
import ShimmerButton from './ShimmerButton';

interface BookingModalProps {
  procedure: Procedure | null;
  onClose: () => void;
  isOpen: boolean;
}

const BookingModal: React.FC<BookingModalProps> = ({ procedure, onClose, isOpen }) => {
  const [isMaleVersion, setIsMaleVersion] = useState(false);
  const [formData, setFormData] = useState<BookingFormData>({
    name: '',
    preferredDate: '',
    preferredTime: '',
    paymentMethod: '',
    observations: '',
  });

  // Reset state when modal opens/closes
  useEffect(() => {
    if (!isOpen) {
        setIsMaleVersion(false);
        setFormData({ name: '', preferredDate: '', preferredTime: '', paymentMethod: '', observations: '' });
    }
  }, [isOpen]);

  if (!isOpen || !procedure) return null;

  const currentProcedureName = isMaleVersion && procedure.maleVersion ? procedure.maleVersion.name : procedure.name;
  const currentPrice = isMaleVersion && procedure.maleVersion ? procedure.maleVersion.price : procedure.price;

  const isValid = formData.name && formData.preferredDate && formData.preferredTime;

  const generateWhatsAppMessage = () => {
    const studioPhone = '5542999722042';
    const message = `Olá, Joyci! Gostaria de agendar: *${currentProcedureName}* (${currentPrice}).

*Meus Dados:*
Nome: ${formData.name}
Data: ${new Date(formData.preferredDate).toLocaleDateString('pt-BR')} às ${formData.preferredTime}
Obs: ${formData.observations || 'Nenhuma'}

Aguardo confirmação! ✨`;

    return `https://wa.me/${studioPhone}?text=${encodeURIComponent(message)}`;
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-end md:items-center justify-center">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/80 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      ></div>

      {/* Modal / Drawer */}
      <div className="relative w-full md:w-[600px] bg-[#121212] md:rounded-2xl rounded-t-2xl shadow-2xl border border-white/10 flex flex-col max-h-[90vh] animate-[slideUp_0.3s_ease-out]">

        {/* Header */}
        <div className="flex items-center justify-between p-5 border-b border-white/5">
            <div>
                <h2 className="font-serif text-2xl text-amber-100">{procedure.name}</h2>
                <p className="text-amber-200/60 text-sm mt-1">{currentPrice}</p>
            </div>
            <button onClick={onClose} className="p-2 bg-white/5 rounded-full hover:bg-white/10 transition">
                <svg className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
            </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-5 md:p-8 space-y-6">

            {/* Quick Details Pills */}
            <div className="flex flex-wrap gap-2 text-xs">
                 {procedure.maleVersion && (
                     <button 
                        onClick={() => setIsMaleVersion(!isMaleVersion)}
                        className={`px-3 py-1.5 rounded-lg border transition-all ${isMaleVersion ? 'bg-amber-500/20 border-amber-500 text-amber-200' : 'bg-white/5 border-white/10 text-gray-400'}`}
                     >
                        Versão Masculina
                     </button>
                 )}
                 <div className="px-3 py-1.5 rounded-lg bg-white/5 border border-white/10 text-gray-300">
                    Duração média: 1h-2h
                 </div>
            </div>

            <div className="space-y-4">
                <div className="group">
                    <label className="block text-xs uppercase tracking-wider text-gray-500 mb-1.5">Seu Nome</label>
                    <input 
                        type="text" 
                        value={formData.name}
                        onChange={(e) => setFormData({...formData, name: e.target.value})}
                        className="w-full bg-[#0a0a0a] border border-white/10 rounded-xl p-4 text-white placeholder-gray-600 focus:border-amber-500/50 focus:ring-1 focus:ring-amber-500/50 outline-none transition"
                        placeholder="Como gostaria de ser chamada?"
                    />
                </div>

                <div className="grid grid-cols-2 gap-4">
                     <div className="group">
                        <label className="block text-xs uppercase tracking-wider text-gray-500 mb-1.5">Data</label>
                        <input 
                            type="date" 
                            value={formData.preferredDate}
                            onChange={(e) => setFormData({...formData, preferredDate: e.target.value})}
                            className="w-full bg-[#0a0a0a] border border-white/10 rounded-xl p-4 text-white focus:border-amber-500/50 focus:ring-1 focus:ring-amber-500/50 outline-none transition"
                        />
                    </div>
                    <div className="group">
                        <label className="block text-xs uppercase tracking-wider text-gray-500 mb-1.5">Horário</label>
                        <input 
                            type="time" 
                            value={formData.preferredTime}
                            onChange={(e) => setFormData({...formData, preferredTime: e.target.value})}
                            className="w-full bg-[#0a0a0a] border border-white/10 rounded-xl p-4 text-white focus:border-amber-500/50 focus:ring-1 focus:ring-amber-500/50 outline-none transition"
                        />
                    </div>
                </div>

                 <div className="group">
                    <label className="block text-xs uppercase tracking-wider text-gray-500 mb-1.5">Observações (Opcional)</label>
                    <textarea 
                        rows={2}
                        value={formData.observations}
                        onChange={(e) => setFormData({...formData, observations: e.target.value})}
                        className="w-full bg-[#0a0a0a] border border-white/10 rounded-xl p-4 text-white placeholder-gray-600 focus:border-amber-500/50 focus:ring-1 focus:ring-amber-500/50 outline-none transition"
                        placeholder="Alergias, dúvidas ou pedidos especiais..."
                    />
                </div>
            </div>
        </div>

        {/* Footer Actions */}
        <div className="p-5 border-t border-white/5 bg-[#0a0a0a]/50 backdrop-blur-md">
            <a 
                href={isValid ? generateWhatsAppMessage() : '#'}
                target="_blank"
                rel="noopener noreferrer"
                onClick={(e) => { if(!isValid) e.preventDefault(); else onClose(); }}
                className={`block w-full ${!isValid ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
                <ShimmerButton className="w-full py-4 text-base font-bold shadow-lg shadow-amber-900/20">
                    Confirmar no WhatsApp
                </ShimmerButton>
            </a>
            <p className="text-center text-[10px] text-gray-600 mt-3">
                Você será redirecionada para o WhatsApp do Studio para finalizar.
            </p>
        </div>
      </div>
    </div>
  );
};

