import React, { useState, useEffect, useMemo } from 'react';
import { Procedure, Category, SubCategory } from '../types';
import { CATEGORIES } from '../data/procedures';
import ProcedureCard from '../components/ProcedureCard';

interface CatalogPageProps {
  onBook: (procedure: Procedure) => void;
}

// Flatten all procedures helper
const getAllProcedures = (categories: Category[]) => {
    let all: (Procedure & { categoryId: string })[] = [];
    categories.forEach(cat => {
        if(cat.procedures) {
            all = [...all, ...cat.procedures.map(p => ({...p, categoryId: cat.id}))];
        }
        if(cat.subCategories) {
            cat.subCategories.forEach(sub => {
                all = [...all, ...sub.procedures.map(p => ({...p, categoryId: cat.id}))];
            });
        }
    });
    return all;
};

const CatalogPage: React.FC<CatalogPageProps> = ({ onBook }) => {
  const [activeCategory, setActiveCategory] = useState<string>('todos');
  const [searchTerm, setSearchTerm] = useState('');

  // Memoize the flattened list
  const allProcedures = useMemo(() => getAllProcedures(CATEGORIES), []);

  // Filter Logic
  const filteredProcedures = useMemo(() => {
    return allProcedures.filter(proc => {
        const matchesCategory = activeCategory === 'todos' || proc.categoryId === activeCategory;
        const matchesSearch = proc.name.toLowerCase().includes(searchTerm.toLowerCase());
        return matchesCategory && matchesSearch;
    });
  }, [activeCategory, searchTerm, allProcedures]);

  return (
    <div className="pb-24 pt-4 px-4 md:px-8 max-w-7xl mx-auto min-h-screen">

        {/* Header Area */}
        <div className="mb-6 flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div>
                <h1 className="font-serif text-3xl text-amber-100">Catálogo</h1>
                <p className="text-gray-400 text-sm mt-1">Escolha seu procedimento ideal.</p>
            </div>

            {/* Search Bar */}
            <div className="relative w-full md:w-64">
                <input 
                    type="text"
                    placeholder="Buscar procedimento..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full bg-white/5 border border-white/10 rounded-full py-2.5 pl-10 pr-4 text-sm text-white focus:outline-none focus:border-amber-400/50 focus:bg-white/10 transition-all"
                />
                <svg className="absolute left-3.5 top-3 h-4 w-4 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
            </div>
        </div>

        {/* Filter Scroll (Instagram Style) */}
        <div className="sticky top-0 md:top-20 z-30 bg-[#050505]/95 backdrop-blur-md py-3 -mx-4 px-4 md:mx-0 md:px-0 mb-6 overflow-x-auto no-scrollbar flex space-x-3 border-b border-white/5">
            <button 
                onClick={() => setActiveCategory('todos')}
                className={`flex-shrink-0 px-5 py-2 rounded-full text-sm font-medium transition-all duration-300 border ${
                    activeCategory === 'todos' 
                    ? 'bg-amber-100 text-black border-amber-100 shadow-[0_0_15px_rgba(251,191,36,0.3)]' 
                    : 'bg-white/5 text-gray-400 border-white/10 hover:border-white/30 hover:text-white'
                }`}
            >
                Todos
            </button>
            {CATEGORIES.map(cat => (
                <button 
                    key={cat.id}
                    onClick={() => setActiveCategory(cat.id)}
                    className={`flex-shrink-0 px-5 py-2 rounded-full text-sm font-medium transition-all duration-300 border ${
                        activeCategory === cat.id 
                        ? 'bg-amber-100 text-black border-amber-100 shadow-[0_0_15px_rgba(251,191,36,0.3)]' 
                        : 'bg-white/5 text-gray-400 border-white/10 hover:border-white/30 hover:text-white'
                    }`}
                >
                    {cat.name.replace(' - ', ' ')}
                </button>
            ))}
        </div>

        {/* Masonry Grid */}
        {filteredProcedures.length > 0 ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-6">
                {filteredProcedures.map((proc) => (
                    <ProcedureCard 
                        key={proc.id} 
                        procedure={proc} 
                        onClick={() => onBook(proc)} 
                    />
                ))}
            </div>
        ) : (
            <div className="flex flex-col items-center justify-center py-20 text-center">
                <div className="p-4 rounded-full bg-white/5 mb-4">
                     <svg className="h-8 w-8 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                </div>
                <h3 className="text-lg font-medium text-gray-300">Nenhum procedimento encontrado</h3>
                <p className="text-gray-500 text-sm mt-1">Tente buscar por outro termo ou categoria.</p>
                <button onClick={() => {setSearchTerm(''); setActiveCategory('todos')}} className="mt-4 text-amber-300 text-sm hover:underline">Limpar filtros</button>
            </div>
        )}
    </div>
  );
};

