import React, { useState } from 'react';
import { Procedure, Category, SubCategory } from '../types';
import { CATEGORIES } from '../public/data/procedures';
import ProcedureCard from '../components/ProcedureCard';
import BackButton from '../components/BackButton';

interface CatalogPageProps {
  onProcedureSelect: (procedure: Procedure) => void;
}

const CatalogPage: React.FC<CatalogPageProps> = ({ onProcedureSelect }) => {
  // Estado para controlar qual categoria principal está aberta (Menu Suspenso)
  // Inicia com a primeira categoria aberta para melhor UX
  const [openCategoryId, setOpenCategoryId] = useState<string | null>(CATEGORIES[0]?.id ?? null);

  // Estado para controlar subcategorias (ex: dentro de Cílios -> Volume Russo)
  const [openSubCategoryId, setOpenSubCategoryId] = useState<string | null>(null);

  const handleToggleCategory = (categoryId: string) => {
    setOpenCategoryId(prevId => {
      // Se clicar na que já está aberta, fecha. Se for outra, abre a nova e fecha a anterior.
      const newId = prevId === categoryId ? null : categoryId;
      // Ao trocar de categoria principal, resetamos a subcategoria
      if (newId !== prevId) {
        setOpenSubCategoryId(null);
      }
      return newId;
    });
  };

  const handleToggleSubCategory = (subCategoryId: string) => {
    setOpenSubCategoryId(prevId => (prevId === subCategoryId ? null : subCategoryId));
  };

  return (
    <div className="container mx-auto py-8 md:py-12 px-4 flex flex-col items-center animate-fade-in min-h-screen">
       <div className="w-full max-w-6xl self-start">
        <BackButton className="mb-8" />
      </div>

      {/* Cabeçalho da Página */}
      <div className="text-center mb-8 md:mb-12 max-w-3xl">
        <h1 className="font-display text-4xl md:text-5xl text-amber-100">Catálogo de Serviços</h1>
        <p className="mt-4 max-w-2xl mx-auto text-sm md:text-base text-amber-100/70">
          Selecione uma categoria abaixo para visualizar os procedimentos disponíveis.
        </p>
      </div>

      {/* Lista de Categorias (Estilo Menu Suspenso / Acordeão) */}
      <div className="w-full max-w-6xl grid grid-cols-1 gap-4">
        {CATEGORIES.map((category: Category) => {
          const isCategoryOpen = openCategoryId === category.id;

          return (
            <div key={category.id} className={`border ${isCategoryOpen ? 'border-amber-200/40 bg-gray-900' : 'border-amber-200/10 bg-gray-900/50'} rounded-lg overflow-hidden transition-all duration-300`}>
              {/* Botão Principal da Categoria */}
              <button
                onClick={() => handleToggleCategory(category.id)}
                className="w-full flex justify-between items-center p-5 text-left hover:bg-amber-200/5 transition-colors focus:outline-none"
                aria-expanded={isCategoryOpen}
              >
                <div className="flex items-center gap-4">
                    {/* Ícone decorativo baseado no estado */}
                    <div className={`w-1 h-8 rounded-full transition-all duration-300 ${isCategoryOpen ? 'bg-amber-400 shadow-[0_0_10px_rgba(251,191,36,0.5)]' : 'bg-gray-700'}`}></div>
                    <h2 className={`font-serif text-xl md:text-2xl transition-colors ${isCategoryOpen ? 'text-amber-100' : 'text-amber-100/70'}`}>
                    {category.name}
                    </h2>
                </div>

                {/* Seta de indicação */}
                <span
                  className={`inline-block text-amber-200 transform transition-transform duration-300 ${isCategoryOpen ? 'rotate-180' : ''}`}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                  </svg>
                </span>
              </button>

              {/* Conteúdo da Categoria (Procedimentos ou Subcategorias) */}
              <div
                className={`transition-all duration-500 ease-in-out grid ${
                  isCategoryOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0'
                }`}
              >
                <div className="overflow-hidden">
                    {/* Caso 1: A categoria tem procedimentos diretos (sem subcategoria) */}
                    {category.procedures && category.procedures.length > 0 && (
                        <div className="p-4 md:p-6 border-t border-amber-200/10 bg-black/20">
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {category.procedures.map((procedure) => (
                                    <ProcedureCard 
                                        key={procedure.id} 
                                        procedure={procedure} 
                                        onClick={onProcedureSelect}
                                    />
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Caso 2: A categoria tem Subcategorias (ex: Lash -> Lifting, Extensões) */}
                    {category.subCategories && category.subCategories.length > 0 && (
                        <div className="p-2 md:p-4 border-t border-amber-200/10 bg-black/20 space-y-3">
                            {category.subCategories.map((subCategory: SubCategory) => {
                                const isSubCategoryOpen = openSubCategoryId === subCategory.id;
                                return (
                                    <div key={subCategory.id} className="border border-amber-200/10 rounded-md overflow-hidden bg-gray-800/40">
                                        <button
                                            onClick={() => handleToggleSubCategory(subCategory.id)}
                                            className="w-full flex justify-between items-center p-3 md:p-4 text-left hover:bg-amber-200/5 transition-colors"
                                            aria-expanded={isSubCategoryOpen}
                                        >
                                            <h3 className="font-serif text-base md:text-lg text-amber-100/90 pl-2">
                                                {subCategory.name}
                                            </h3>
                                            <span
                                                className={`inline-block text-amber-200/80 transform transition-transform duration-300 ${isSubCategoryOpen ? 'rotate-180' : ''}`}
                                            >
                                               <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                                  <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                                                </svg>
                                            </span>
                                        </button>

                                        {/* Grid de Procedimentos da Subcategoria */}
                                        <div
                                            className={`transition-all duration-500 ease-in-out grid ${
                                                isSubCategoryOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0'
                                            }`}
                                        >
                                            <div className="overflow-hidden">
                                                <div className="p-4 md:p-6 border-t border-amber-200/10 bg-gray-900/50">
                                                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                                        {subCategory.procedures.map((procedure) => (
                                                            <ProcedureCard 
                                                                key={procedure.id} 
                                                                procedure={procedure} 
                                                                onClick={onProcedureSelect}
                                                            />
                                                        ))}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                    )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default CatalogPage;

