        className="relative bg-gray-900 border border-amber-200/20 shadow-2xl shadow-amber-900/40 rounded-xl w-full max-w-4xl flex flex-col md:flex-row max-h-[95vh] overflow-hidden" 
        onClick={(e) => e.stopPropagation()}
