             {procedure.price.split('|').map((part, index) => (
                <span key={index} className="text-sm font-semibold text-amber-200 whitespace-nowrap">
                   {part.replace('Aplicação:', 'Aplic:').replace('Manutenção:', 'Manut:').trim()}
